# For each of the 15 classes of words w of length 4 (up to renaming letters), take the transition
# group G(w) <= UT5(F2) of the mod-2 counting automaton of w (state v in F2^5, v0 = 1, v_i = number
# of occurrences of w[0:i] as a subsequence mod 2), generated by the letter matrices.  Report |G|,
# |G'|, |G''|, |Z(G)|, and whether a central involution z flips the count: (z m)_{04} = m_{04} + 1
# for every m in G (listed per central involution).  "span" says whether the rows m[0] (m in G)
# and the columns m[.][4] (m in G) each span F2^5; with span and |G''| > 1 the barrier argument of
# M28-STARHEIGHT-LIE-BARRIER.md applies to w (a recognizer maps onto G(w), whose image of a Sylow
# 2-subgroup is all of G(w)).
N = 5
def mat_of_letter(w, x):
    # row-vector action v -> v M; letter x: for i from len-1 down to 0, if w[i]==x: v[i+1] ^= v[i]
    rows = []
    for k in range(N):
        v = [0] * N; v[k] = 1
        for i in range(len(w) - 1, -1, -1):
            if w[i] == x: v[i + 1] ^= v[i]
        rows.append(sum(b << j for j, b in enumerate(v)))
    return tuple(rows)
def mul(A, B):  # (A B) rows: row_k(A B) = sum_j A[k][j] row_j(B)
    out = []
    for r in A:
        s = 0; j = 0
        while r:
            if r & 1: s ^= B[j]
            r >>= 1; j += 1
        out.append(s)
    return tuple(out)
I = tuple(1 << k for k in range(N))
def inv(A, G=None):
    P = A
    while True:
        Q = mul(P, A)
        if Q == I: return P
        P = Q
def closure(gens):
    seen = {I}; fr = [I]
    while fr:
        nf = []
        for m in fr:
            for g in gens:
                h = mul(m, g)
                if h not in seen: seen.add(h); nf.append(h)
        fr = nf
    return seen
def comm(a, b): return mul(mul(a, b), mul(inv(a), inv(b)))
def normal_closure(S, gens):
    S = set(S)
    while True:
        H = closure(list(S))
        new = {mul(mul(g, h), inv(g)) for h in S for g in gens} - H
        if not new: return H
        S |= new
def derived(H, gens):
    # derived subgroup of H = <gens>: normal closure in H of the commutators of generators
    return normal_closure({comm(a, b) for a in gens for b in gens}, gens)
def gens_of(H):
    # a small generating set of H (greedy)
    gs = []; cur = {I}
    for h in sorted(H):
        if h not in cur: gs.append(h); cur = closure(gs)
    return gs
def entry(m, i, j): return (m[i] >> j) & 1
def rank(vecs):
    basis = []
    for v in vecs:
        for b in basis: v = min(v, v ^ b)
        if v: basis.append(v)
    return len(basis)
def spans(G):
    rows = [m[0] for m in G]
    cols = [sum(entry(m, k, 4) << k for k in range(N)) for m in G]
    return rank(rows) == N and rank(cols) == N
def canon_words():
    out = []
    def rec(w, mx):
        if len(w) == 4: out.append(''.join(w)); return
        for c in range(mx + 2):
            if c < 4: rec(w + ["abcd"[c]], max(mx, c))
    rec([], -1)
    return out
print("w     |G|   |G'|  |G''| |Z|  span  central involutions flipping the count")
for w in canon_words():
    letters = sorted(set(w))
    gens = [mat_of_letter(w, x) for x in letters]
    G = closure(gens)
    D1 = derived(G, gens)
    D2 = derived(D1, gens_of(D1))
    Z = [z for z in G if all(mul(z, g) == mul(g, z) for g in gens)]
    invs = [z for z in Z if z != I and mul(z, z) == I]
    flips = sum(all(entry(mul(z, m), 0, 4) != entry(m, 0, 4) for m in G) for z in invs)
    print("%-5s %-5d %-5d %-5d %-4d %-5s %d of %d" % (w, len(G), len(D1), len(D2), len(Z),
                                                   "yes" if spans(G) else "no", flips, len(invs)))
